#include <stdio.h>

int main(void) {
    int day = 2;
    switch (day) {
        case 1: printf("Mon\n");
        case 2: printf("Tue\n");
        case 3: printf("Wed\n"); break;
        case 4: printf("Thu\n");
        default: printf("?\n");
    }
    return 0;
}

